def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Given a grid with H rows and W columns consisting of '1', '2', '3', and '?',
    count replacements that make every pair of edge-adjacent cells different.
    Return the count modulo 998244353.
    """
    mod = 998244353

    # Transfer across the shorter dimension. This bounds the row-state count by
    # 3 * 2**(min(H, W)-1), with min(H, W) <= 14 under the input constraints.
    if W > H:
        grid = [''.join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Encode each horizontally valid row as a base-3 integer, and retain its
    # digits for compatibility checks.
    states = []
    state_id = {}
    for first in range(3):
        row = [first]
        def build(pos):
            if pos == W:
                code = 0
                for x in row:
                    code = code * 3 + x
                state_id[code] = len(states)
                states.append(tuple(row))
                return
            for x in range(3):
                if x != row[-1]:
                    row.append(x)
                    build(pos + 1)
                    row.pop()
        build(1)

    # Filter the row-state domain for each input row.
    allowed = []
    for line in grid:
        fixed = [None if ch == '?' else int(ch) - 1 for ch in line]
        allowed.append([
            i for i, state in enumerate(states)
            if all(fixed[c] is None or fixed[c] == state[c] for c in range(W))
        ])

    dp = [0] * len(states)
    for i in allowed[0]:
        dp[i] = 1

    # For each active state, generate only next rows that differ vertically
    # and remain horizontally valid.
    for r in range(1, H):
        next_dp = [0] * len(states)
        valid_next = set(allowed[r])
        for i, ways in enumerate(dp):
            if not ways:
                continue
            prev = states[i]
            row = [0] * W

            def generate(c):
                if c == W:
                    code = 0
                    for x in row:
                        code = code * 3 + x
                    j = state_id[code]
                    if j in valid_next:
                        next_dp[j] = (next_dp[j] + ways) % mod
                    return
                for x in range(3):
                    if x != prev[c] and (c == 0 or x != row[c - 1]):
                        row.append(x) if False else None
                        # Assign in place; row starts as a fixed-size list.
                        row[c] = x
                        generate(c + 1)

            generate(0)
        dp = next_dp
    return sum(dp) % mod

from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangles can exactly cover an h by w grid.

    Each tile can be rotated, and any number of tiles may be left unused.
    """
    if n != len(tiles) or h <= 0 or w <= 0:
        return False

    target_area = h * w
    full_mask = (1 << target_area) - 1
    areas = [a * b for a, b in tiles]
    if not tiles or max(areas) > target_area or sum(areas) < target_area:
        return False

    # Precompute each tile's legal placements. A placement is a bitset of
    # grid cells, and the cell index narrows candidates during exact cover.
    by_cell = [[] for _ in range(target_area)]
    for idx, (a, b) in enumerate(tiles):
        options = set()
        for ph, pw in {(a, b), (b, a)}:
            if ph > h or pw > w:
                continue
            for y in range(h - ph + 1):
                for x in range(w - pw + 1):
                    mask = 0
                    for yy in range(y, y + ph):
                        row_start = yy * w
                        for xx in range(x, x + pw):
                            mask |= 1 << (row_start + xx)
                    options.add(mask)
        for mask in options:
            bits = mask
            while bits:
                bit = bits & -bits
                by_cell[bit.bit_length() - 1].append((idx, mask))
                bits -= bit

    all_tiles = (1 << n) - 1
    require_all = sum(areas) == target_area

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int, remaining_area: int) -> bool:
        if occupied == full_mask:
            return not require_all or used == all_tiles
        uncovered_area = target_area - occupied.bit_count()
        if remaining_area < uncovered_area:
            return False

        # Every completion must place a tile over the first uncovered cell.
        empty = full_mask ^ occupied
        cell = (empty & -empty).bit_length() - 1
        for idx, mask in by_cell[cell]:
            tile_bit = 1 << idx
            if not (used & tile_bit) and not (occupied & mask):
                if search(occupied | mask, used | tile_bit,
                          remaining_area - areas[idx]):
                    return True
        return False

    return search(0, 0, sum(areas))

