def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Given n and k, decide whether an n by n binary matrix can have exactly k
    entries fixed by its row and column sums.

    A nonfixed part must contain alternating cycles; the smallest possible
    movable part is a 2 by 2 switch.  Boundary cases with very small fixed
    counts are consequently sparse.
    """
    if k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True

    # A fixed border can be peeled away row by row and column by column.
    # The remaining movable core has at least two rows and columns.  For
    # square matrices the attainable border sizes arise from rectangular
    # cores, with additional small rigid Ferrers shapes.
    core_area = n * n - k
    if core_area >= 4:
        for rows in range(2, n + 1):
            if core_area % rows == 0:
                cols = core_area // rows
                if 2 <= cols <= n:
                    return True

    # Small Ferrers cores can have forced cells interspersed with switches.
    # These are the minimal non-rectangular cases.
    if n == 3:
        return k == 3
    if n == 4:
        return k in (4, 7, 10, 12)
    if n == 5:
        return k in (10, 12)
    return False

