from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Given section lengths and two sensor types, return the minimum cost to cover
    every section, respecting the global maximum count of each sensor type.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2

    # A state is the number of each sensor used. For any section, it is enough
    # to consider the least number of type 2 sensors for each possible number
    # of type 1 sensors.
    states = {(0, 0)}
    for demand in sections[:n]:
        max_x = min(k1, (demand + l1 - 1) // l1)
        options = []
        for x in range(max_x + 1):
            y = max(0, (demand - x * l1 + l2 - 1) // l2)
            if y <= k2:
                options.append((x, y))

        # Remove locally dominated choices.
        best_y = k2 + 1
        local = []
        for x, y in options:
            if y < best_y:
                local.append((x, y))
                best_y = y
        if not local:
            return -1

        combined = set()
        for used1, used2 in states:
            for x, y in local:
                total1, total2 = used1 + x, used2 + y
                if total1 <= k1 and total2 <= k2:
                    combined.add((total1, total2))
        if not combined:
            return -1

        # Keep only states that are not dominated in both sensor counts.
        by_type1 = {}
        for x, y in combined:
            if y < by_type1.get(x, k2 + 1):
                by_type1[x] = y
        states = set()
        best_y = k2 + 1
        for x in sorted(by_type1):
            y = by_type1[x]
            if y < best_y:
                states.add((x, y))
                best_y = y

    return min((x * c1 + y * c2 for x, y in states), default=-1)

