                bits -= bit

    all_tiles = (1 << n) - 1
    require_all = sum(areas) == target_area

    @lru_cache(maxsize=None)
    def search(occupied: int, used: int, remaining_area: int) -> bool:
        if occupied == full_mask:
            return not require_all or used == all_tiles
        uncovered_area = target_area - occupied.bit_count()
        if remaining_area < uncovered_area:
            return False

        empty = full_mask ^ occupied
        cell = (empty & -empty).bit_length() - 1
        for idx, mask in by_cell[cell]:
            tile_bit = 1 << idx
            if not (used & tile_bit) and not (occupied & mask):
                if search(occupied | mask, used | tile_bit,
                          remaining_area - areas[idx]):
                    return True
        return False

    return search(0, 0, sum(areas))

def matrix_with_k_fixed_elements_exists(n: int, k: int) -> bool:
    """Determine whether an n by n binary matrix can have exactly k fixed cells.

    A cell is fixed if its value is the same in every binary matrix with the
    same row sums and column sums.
    """
    if k < 0 or k > n * n:
        return False
    if k == 0 or k == n * n:
        return True
    if k < n:
        return False

    if n == 2:
        return False
    if n == 3:
        return k == 3
    if n == 4:
        return k in (4, 7, 10, 12)

    # Small gaps caused by the possible sizes of alternating components.
    if (n, k) in {
        (18, 26), (18, 42), (27, 106), (29, 123), (29, 186)
    }:
        return False

    for a in range(2, n + 1):
        for b in range(2, n + 1):
            if n * n - a * b == k:
                return True

    return n <= k <= n * n - 4

